1195	/* ---------- evidence panel: KWIC, parallel loci, n-gram phraseology ----------
1196	   Point 5 of the critique. A row in either report is a CLAIM, and a claim whose
1197	   evidence is one click away is checkable; one behind a separate page is not
1198	   checked. Everything here reads the same `window=False` token stream the row's
1199	   numbers came from, so a count and its loci cannot disagree. */
1200	let _ARCH_CTX = null;
1201	
1202	/* The pooled key is derived SERVER-SIDE from the displayed word, by the same
1203	   function the count used. The client never pools anything itself: a second
1204	   implementation of the correspondence rules in JavaScript is a second place
1205	   for them to be wrong. */
1206	function _evUrl(ctx, what, params) {
1207	  const qs = new URLSearchParams(Object.assign({
1208	    variants: ctx.variants === "all" ? "all" : ctx.variants,
1209	    // A lemma row's loci have to be found by LEMMA, not by the headword
1210	    // string: ὁπλίτης occurs as ὁπλίτας, ὁπλῖται, ὁπλιτῶν, and a key lookup on
1211	    // the nominative would return a handful of tokens that do not add up to the
1212	    // count printed beside the row. The server derives the form set from the
1213	    // same index the row came from.
1214	    mode: ctx.mode || "lexical",
1215	  }, params));
1216	  return API(`/${what}/${ctx.a1}/${ctx.w1}/${ctx.a2}/${ctx.w2}?${qs}`);
1217	}
1218	
1219	function _evPanel() { return document.getElementById("arch-evidence"); }
1220	
1221	async function _evLoad(ctx, what, params, render) {
1222	  const p = _evPanel();
1223	  if (!p) return;
1224	  p.innerHTML = `<div class="reader-empty">Loading…</div>`;
1225	  let d;
1226	  try { d = await fetchJSON(_evUrl(ctx, what, params)); }
1227	  catch (e) {
1228	    if (p.isConnected) p.innerHTML = `<div class="reader-empty">Error: ${esc(String(e && e.message || e))}</div>`;
1229	    return;
1230	  }
1231	  if (!p.isConnected) return;         // view changed while loading
1232	  if (d.error) { p.innerHTML = `<div class="reader-empty">${esc(d.error)}</div>`; return; }
1233	  p.innerHTML = render(d);
1234	  p.scrollIntoView({ block: "nearest", behavior: "smooth" });
1235	}
1236	
1237	function _evCtxLine(d, word) {
1238	  // A rule panel is about a spelling CLASS, not a word, and saying so is the
1239	  // difference between "ξυ is a word that occurs 1889 times" (nonsense) and
1240	  // "1889 tokens are written with ξυ-" (the actual finding).
1241	  const title = d.rule
1242	    ? `<b>rule</b> <b class="greek">${esc(d.word)}</b>
1243	       <span class="muted">· every token wearing the marked spelling</span>`
1244	    : `<b class="greek">${esc(word)}</b>`;
1245	  return `<div class="ev-head">${title}
1246	    <span class="muted">A = ${esc(d.work1.title || d.work1.aid)},
1247	    B = ${esc(d.work2.title || d.work2.aid)}</span>
1248	    <button class="ev-close" type="button" data-ev-close="1">close</button></div>`;
1249	}
1250	
1251	function _evHits(side, key) {
1252	  const hits = (side.hits || {})[key] || [];
1253	  if (!hits.length) return `<div class="reader-empty">no occurrences</div>`;
1254	  return `<ol class="ev-kwic">${hits.map((h) => `
1255	    <li><span class="ev-locus">${esc(h.label)}:${h.index}</span>
1256	      <span class="ev-context greek">${esc(h.before.join(" "))}
1257	        <mark${h.marked && h.marked.length ? ` class="ev-marked" title="marked spelling: ${esc(h.marked.join(", "))}"` : ""}>${esc(h.hit)}</mark>
1258	        ${esc(h.after.join(" "))}</span>
1259	      <button class="ev-mini" type="button" data-ev-par="${esc(h.label)}:${h.index}"
1260	        title="find the most similar sentences in A">‖ parallel</button></li>`).join("")}</ol>`;
1261	}
1262	
1263	function _evLociHtml(d, word) {
1264	  const k = d.key;
1265	  const ta = d.work_a.truncated[k], tb = d.work_b.truncated[k];
1266	  return _evCtxLine(d, word) + `
1267	    <div class="ev-cols">
1268	      <div><div class="ev-cap">in A · ${d.work_a.n_hits[k] || 0} occurrence(s)${
1269	        ta ? ` <span class="warn">(showing the first ${(d.work_a.hits[k] || []).length})</span>` : ""}</div>
1270	        ${_evHits(d.work_a, k)}</div>
1271	      <div><div class="ev-cap">in B · ${d.work_b.n_hits[k] || 0} occurrence(s)${
1272	        tb ? ` <span class="warn">(showing the first ${(d.work_b.hits[k] || []).length})</span>` : ""}</div>
1273	        ${_evHits(d.work_b, k)}</div>
1274	    </div>
1275	    <div class="ev-note muted">±${d.work_a.span} words. A <mark class="ev-marked">highlighted</mark>
1276	    form wears the marked spelling — this is where the register question stops being a
1277	    rate and becomes a text.</div>
1278	    ${d.rule ? `<div class="ev-note muted">Phraseology is keyed on a word, and a rule
1279	    is a class of spellings, not a word a phrase can be formed around — pick a word
1280	    from the lexical report for that.</div>` : ""}
1281	    <div class="ev-actions">
1282	      ${d.rule ? "" : `<button class="more-btn" type="button" data-ev-ngram="2">2-gram phraseology</button>
1283	      <button class="more-btn" type="button" data-ev-ngram="3">3-grams</button>`}
1284	      <label class="live-toggle">min. count in A:
1285	        <input type="number" id="ev-mina" min="1" value="3"></label>
1286	      <label class="live-toggle">max. count in B:
1287	        <input type="number" id="ev-maxb" min="0" value="0"></label>
1288	    </div>`;
1289	}
1290	
1291	function _evNgramsHtml(d, word) {
1292	  const rows = d.contrast.rows || [];
1293	  const body = rows.map((x) => `
1294	    <tr>
1295	      <td class="arch-word greek">${esc((x.display || x.gram).join(" "))}</td>
1296	      <td class="num">${x.count_a}</td>
1297	      <td class="num">${x.count_b}</td>
1298	      <td class="num">${x.rate_a.toFixed(3)}</td>
1299	      <td class="num">${x.rate_b.toFixed(3)}</td>
1300	      <td class="num strong">${x.score.toFixed(2)}</td>
1301	    </tr>`).join("");
1302	  const both = (d.table_a.total || 0) + (d.table_b.total || 0);
1303	  return _evCtxLine(d, word) + `
1304	    <div class="ev-cap">${d.n}-grams of which <b class="greek">${esc(word)}</b> is one member,
1305	      collapsed from A to B${both ? "" : " — nothing to show"}</div>
1306	    ${rows.length ? `<table class="arch-table">
1307	      <thead><tr><th>phrase</th><th class="num">A ×</th><th class="num">B ×</th>
1308	      <th class="num">A /1k</th><th class="num">B /1k</th><th class="num">collapse</th></tr></thead>
1309	      <tbody>${body}</tbody></table>` : `<div class="reader-empty">No phrase of A's
1310	      qualifies at these thresholds. A phrase A used once is noise, not phraseology —
1311	      raise “min. count in A” only to see fewer, not more.</div>`}
1312	    <div class="ev-note muted">Counted over pooled spellings, so A’s <span class="greek">ξυμμαχία</span>
1313	    and B’s <span class="greek">συμμαχία</span> are the same phrase. The phrase column prints
1314	    A’s spelling. Rates divide by the works’ word counts (${d.n_a.toLocaleString()} /
1315	    ${d.n_b.toLocaleString()}), not by the table’s own sums.</div>
1316	    <div class="ev-actions">
1317	      <button class="more-btn" type="button" data-ev-ngram="${d.n === 2 ? 3 : 2}">
1318	        switch to ${d.n === 2 ? "3" : "2"}-grams</button>
1319	      <button class="more-btn" type="button" data-ev-loci="${esc(word)}">occurrences</button>
1320	    </div>`;
1321	}
1322	
1323	function _evParallelHtml(d, word) {
1324	  const r = d.result;
1325	  const q = (d.query_words || []).join(" ");
1326	  const body = (r.hits || []).map((h) => `
1327	    <li><span class="ev-locus">${esc(h.label)}</span>
1328	      <span class="greek">${esc(h.text)}</span>
1329	      <span class="ev-score">${h.score.toFixed(3)}</span>
1330	      ${(h.shared_3.length || h.shared_2.length) ? `<div class="ev-shared">shared:
1331	        ${h.shared_3.map((g) => `<b class="greek">${esc(g)}</b>`).join(" ")}
1332	        ${h.shared_2.map((g) => `<span class="greek">${esc(g)}</span>`).join(" ")}</div>` : ""}</li>`).join("");
1333	  return _evCtxLine(d, word) + `
1334	    <div class="ev-cap">in B: <span class="greek">${esc((d.anchor.before || []).join(" "))}
1335	      <mark>${esc(d.anchor.hit || "")}</mark> ${esc((d.anchor.after || []).join(" "))}</span></div>
1336	    <div class="ev-cap">the most similar sentences in A</div>
1337	    ${body ? `<ol class="ev-parallel">${body}</ol>` : `<div class="reader-empty">No sentence
1338	      of A shares a phrase with this window at the current bar. A shared word is not a
1339	      shared phrase — that is what this bar is for.</div>`}
1340	    <div class="ev-note muted">TF-IDF cosine over sentence bags, using the same engine
1341	    (${esc("_idf / _tfidf / cosine")}) as the reuse search. ${r.n_scored.toLocaleString()}
1342	    sentences scored, ${r.n_dropped} dropped for sharing fewer than the
1343	    required n-grams${r.n_skipped_long ? `, ${r.n_skipped_long} skipped as over-long runs` : ""}.
1344	    <span class="greek">${esc(q.slice(0, 120))}${q.length > 120 ? "…" : ""}</span></div>
1345	    <div class="ev-actions">
1346	      <button class="more-btn" type="button" data-ev-loci="${esc(word)}">occurrences</button>
1347	    </div>`;
1348	}
1349	
1350	/* One delegated handler for the whole results box. The evidence panel is
1351	   replaced wholesale on every load, so per-node listeners would have to be
1352	   re-bound each time — and a listener bound to a node that is about to be
1353	   replaced is exactly how a UI acquires clicks that fire twice. */
1354	function _wireEvidence(box) {
1355	  if (!box || box.dataset.evWired) return;
1356	  box.dataset.evWired = "1";
1357	  box.addEventListener("click", (e) => {
1358	    const t = e.target;
1359	    if (!t || !t.closest) return;
1360	    const close = t.closest("[data-ev-close]");
1361	    if (close) { const p = _evPanel(); if (p) p.innerHTML = ""; return; }
1362	    // The lemma expander comes FIRST among the row handlers but after the
1363	    // evidence panel's own close button, because the breakdown it opens is a
1364	    // row of the same table and carries no answer of its own — it is the
1365	    // disclosure that makes the row checkable. Toggling is idempotent on
1366	    // `hidden`, so no state has to be kept in JS.
1367	    const toggle = t.closest("[data-lemma-toggle]");
1368	    if (toggle) {
1369	      const next = toggle.nextElementSibling;
1370	      if (next && next.classList.contains("lemma-forms")) {
